+
+function writeSnapshot(overrides: Record<string, unknown> = {}): void {
+  writeFileSync(join(runDir, 'snapshot.json'), `${JSON.stringify({
+    schemaVersion: 'lattice.managed_host_run.v1',
+    runId,
