+    schemaVersion: 'lattice.managed_host_run.v1',
+    runId,
+    host: 'codex',
+    storyId: null,
+    phase: 'DEV',
+    agentType: 'output-reader-smoke',
+    reviewRunId: null,
+    lane: null,
+    cwd: root,
